-- Subjects and specializations, generated from Subjects.xlsx.
-- Run AFTER the schema migration that scopes a specialization slug
-- to its subject and creates country_sub_subjects.

START TRANSACTION;

-- 1. The 30 subjects. Re-running updates the name and order rather
--    than failing, so this file is safe to apply twice.
ON DUPLICATE KEY UPDATE name = VALUES(name), status = VALUES(status), display_order = VALUES(display_order), updated_at = NOW(3);

-- 2. Subjects that are no longer part of the taxonomy.
DELETE FROM subjects WHERE slug NOT IN ('agriculture-and-environmental-sciences', 'architecture-and-built-environment', 'arts-humanities-and-social-sciences', 'business-and-management', 'computing-and-information-technology', 'education-pgce-and-teaching', 'engineering', 'science', 'creative-arts-design-and-communication', 'communication-media-and-journalism', 'health-medicine-and-veterinary-studies', 'law', 'hospitality-tourism-and-events', 'sports-and-exercise', 'psychology-and-behavioural-sciences', 'fashion-and-textiles', 'hospitality-culinary-and-food', 'aviation-and-aerospace', 'maritime-and-shipping', 'media-entertainment-and-gaming', 'public-policy-government-and-international-studies', 'economics-and-finance', 'mathematics-and-statistics', 'biological-and-life-sciences', 'pharmaceutical-and-pharmaceutical-sciences', 'social-work-and-community-services', 'transport-and-logistics', 'energy-oil-and-gas', 'security-defence-and-emergency-management', 'emerging-and-interdisciplinary-subjects');

