-- 4. Link every subject and every specialization to every country.
--    This is the agreed default; the admin is what narrows it later.
SELECT UUID(), c.id, s.id, s.display_order, NOW(3) FROM countries c CROSS JOIN subjects s WHERE c.deleted_at IS NULL;

SELECT UUID(), c.id, ss.id, ss.display_order, NOW(3) FROM countries c CROSS JOIN sub_subjects ss WHERE c.deleted_at IS NULL;

-- 5. Check before committing.
SELECT 'subjects' AS what, COUNT(*) AS n FROM subjects
UNION ALL SELECT 'specializations', COUNT(*) FROM sub_subjects
UNION ALL SELECT 'country_subjects', COUNT(*) FROM country_subjects
UNION ALL SELECT 'country_sub_subjects', COUNT(*) FROM country_sub_subjects;

